if _MESSAGES["ru"].keys() != _MESSAGES["en"].keys():
    raise RuntimeError("RU and EN message catalogues must contain identical keys")


def tr(language: str, key: str, **values: object) -> str:
    language = language if language in SUPPORTED_LOCALES else "ru"
    return _MESSAGES[language][key].format(**values)
